#!/usr/bin/env python3
"""Package the Icon256 USB factory image separately from the OTA application."""
# AI: below section was generated by an AI
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import struct

from icon256_release import inspect_firmware, version_from_tag


def inspect_factory(data, version):
    """Check the fixed Icon256 flash layout before advertising offset-zero flashing."""
    if len(data) <= 0x10000 or data[0] != 0xE9 or struct.unpack_from('<H', data, 12)[0] != 9:
        raise ValueError('Expected an ESP32-S3 factory image with bootloader at zero')
    expected = [(1, 2, 0x9000, 0x5000), (1, 0, 0xe000, 0x2000),
                (0, 16, 0x10000, 0x180000), (0, 17, 0x190000, 0x180000),
                (1, 130, 0x310000, 0xf0000)]
    for index, partition in enumerate(expected):
        magic, kind, subtype, offset, size = struct.unpack_from('<HBBII', data, 0x8000 + index * 32)
        if magic != 0x50AA or (kind, subtype, offset, size) != partition:
            raise ValueError('Unexpected Icon256 partition layout')
    inspect_firmware(data[0x10000:], version)


def package(tag, build, boot_app, icon, out):
    """Combine build components without padding into user filesystem or second OTA slot."""
    version, _ = version_from_tag(tag)
    components = [(0, build / 'bootloader.bin', 0x8000),
                  (0x8000, build / 'partitions.bin', 0x9000),
                  (0xe000, boot_app, 0x10000),
                  (0x10000, build / 'firmware.bin', 0x190000)]
    merged = bytearray()
    for offset, path, end in components:
        component = path.read_bytes()
        if not component or offset + len(component) > end:
            raise ValueError(f'Empty or oversized factory component: {path.name}')
        merged.extend(b'\xff' * (offset - len(merged)))
        merged.extend(component)
    inspect_factory(merged, version)
    filename = f'WLED_{version}_ESP32_S3_Icon256.factory.bin'
    out.mkdir(parents=True, exist_ok=True)
    (out / filename).write_bytes(merged)
    shutil.copyfile(icon, out / 'icon256.png')
    manifest = {
        'schemaVersion': 1,
        'app': {
            'id': 'tp-icon-256-wled', 'name': 'WLED for Icon256',
            'description': 'Icon256 word clock, text messages, music equalizer and digital rain.',
            'instructions': 'Connect Icon256 by USB. Back up settings and presets before flashing. '
                            'For an existing WLED installation, the device web UI also offers OTA updates.',
            'supportedDevices': ['tp-icon-256'],
            'tags': ['word-clock', 'led-matrix', 'icon256'],
            'icon': {'asset': 'icon256.png', 'sha256': hashlib.sha256(icon.read_bytes()).hexdigest()},
        },
        'release': {'version': version, 'partitions': [{
            'name': 'Factory firmware', 'asset': filename, 'offset': '0x0',
            'sha256': hashlib.sha256(merged).hexdigest(),
        }]},
    }
    (out / 'app-market.json').write_text(json.dumps(manifest, indent=2) + '\n')
    verify(out / 'app-market.json')


def verify(path):
    """Recheck transported release assets, including the embedded firmware version."""
    manifest = json.loads(path.read_text())
    version, _ = version_from_tag('v' + manifest['release']['version'])
    if manifest['app']['id'] != 'tp-icon-256-wled' or manifest['app']['supportedDevices'] != ['tp-icon-256']:
        raise ValueError('Unexpected app market identity')
    partitions = manifest['release']['partitions']
    if len(partitions) != 1 or partitions[0]['offset'] != '0x0':
        raise ValueError('Factory image must be flashed at zero')
    for reference in [manifest['app']['icon'], *partitions]:
        name = reference['asset']
        if Path(name).name != name or '\\' in name:
            raise ValueError('Asset must be a basename')
        data = (path.parent / name).read_bytes()
        if hashlib.sha256(data).hexdigest() != reference['sha256']:
            raise ValueError('App market asset SHA-256 mismatch')
    inspect_factory((path.parent / partitions[0]['asset']).read_bytes(), version)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--verify', type=Path)
    parser.add_argument('--tag')
    parser.add_argument('--build', type=Path, default=Path('.pio/build/icon256'))
    parser.add_argument('--boot-app', type=Path)
    parser.add_argument('--icon', type=Path, default=Path('tools/icon256-assets/icon256.png'))
    parser.add_argument('--out', type=Path, default=Path('release-artifacts'))
    args = parser.parse_args()
    if args.verify:
        verify(args.verify)
    elif args.tag and args.boot_app:
        package(args.tag, args.build, args.boot_app, args.icon, args.out)
    else:
        parser.error('--tag and --boot-app are required when packaging')


if __name__ == '__main__':
    main()
